// Endpoint is the `streams.private.executions` endpoint.
//
// Subscribe to order status and execution events for this account -- a unified stream replacing WebSocket v1's separate `openOrders` and `ownTrades` channels.
type Endpoint struct {
	core truewire.StreamEndpoint
}

// New returns the endpoint over core.
func New(core truewire.StreamEndpoint) *Endpoint {
	return &Endpoint{core: core}
}

// Subscribe to order status and execution events for this account -- a unified stream replacing WebSocket v1's separate `openOrders` and `ownTrades` channels.
//
// See https://docs.kraken.com/exchange/api-reference/spot-websocket-v2/executions.
func (e *Endpoint) Executions(ctx context.Context, parameters Parameters, opts ...truewire.CallOption) (*truewire.Stream[ExecutionsMessage], error) {
	return truewire.Streamed[ExecutionsMessage](e.ExecutionsRaw(ctx, parameters, opts...))
}

// ExecutionsRaw is Executions without validation: the messages as they came.
func (e *Endpoint) ExecutionsRaw(ctx context.Context, parameters Parameters, opts ...truewire.CallOption) (*truewire.Stream[json.RawMessage], error) {
	body, err := truewire.Dump(parameters)
	if err != nil {
		return nil, err
	}
	return e.core.Subscribe(ctx, truewire.SubscribeCall{Channel: "executions", Parameters: body, Options: truewire.Options(opts...)})
}
